// Middleware validates token type, applies OIDC or SAML validation,
// fetches tenant policy, enforces claims/audience/rate limits before routing
app.use(async (req, res, next) => {
  const policy = await policyStore.get(req.tenantId);
  const validation = req.isSaml ? validateSAML : validateOIDC;
  if (!(await validation(req.token, policy))) {
    return res.status(403).json({ error: 'Policy violation' });
  }
  await enforceRateLimit(req, policy);
  next();
});
```

